function proc(o) {
  let t = 0;
  for (let i = 0; i < o.items.length; i++) {
    t += o.items[i].price * o.items[i].qty;
  }
  if (o.coupon) {
    if (o.coupon === "SAVE10") t = t * 0.9;
    else if (o.coupon === "SAVE20") t = t * 0.8;
  }
  let s = t > 50 ? 0 : 5.99;
  let total = t + s;
  if (total < 0) throw new Error("bad total");
  console.log("order " + o.id + " total " + total);
  return total;
}

// after: the same behaviour, split into named, single purpose functions
function processOrder(order) {
  const subtotal = calculateSubtotal(order.items);
  const discountedTotal = applyCoupon(subtotal, order.coupon);
  const shippingCost = calculateShipping(discountedTotal);
  const total = discountedTotal + shippingCost;

  validateTotal(total);
  logOrderTotal(order.id, total);

  return total;
}

function calculateSubtotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function applyCoupon(amount, coupon) {
  const discounts = { SAVE10: 0.9, SAVE20: 0.8 };
  const multiplier = discounts[coupon] ?? 1;
  return amount * multiplier;
}

function calculateShipping(amount) {
  const FREE_SHIPPING_THRESHOLD = 50;
  const STANDARD_SHIPPING_COST = 5.99;
  return amount > FREE_SHIPPING_THRESHOLD ? 0 : STANDARD_SHIPPING_COST;
}

function validateTotal(total) {
  if (total < 0) throw new Error("Order total cannot be negative");
}

function logOrderTotal(orderId, total) {
  console.log(`Order ${orderId} total: ${total}`);
}

