    double t = 0;
    for (const Item& item : o.getItems()) {
        t += item.getPrice() * item.getQty();
    }
    if (!o.getCoupon().empty()) {
        if (o.getCoupon() == "SAVE10") t = t * 0.9;
        else if (o.getCoupon() == "SAVE20") t = t * 0.8;
    }
    double s = t > 50 ? 0 : 5.99;
    double total = t + s;
    if (total < 0) throw std::runtime_error("bad total");
    std::cout << "order " << o.getId() << " total " << total << std::endl;
    return total;
}

