}

double applyCoupon(double amount, const std::string& coupon) {
    if (coupon == "SAVE10") return amount * 0.9;
    if (coupon == "SAVE20") return amount * 0.8;
    return amount;
}

double calculateShipping(double amount) {
    const double FREE_SHIPPING_THRESHOLD = 50;
